import type { Action, ImageRef, Spacing, Tone } from '../../../parts/kinds';

export const HERO_VARIANTS = ['centered', 'split', 'stacked', 'overlay', 'code', 'poster', 'panel'] as const;
export type HeroVariant = (typeof HERO_VARIANTS)[number];

/** The code window beside the text: a short example of the product in use, highlighted at build time. */
export interface HeroCode {
  /** In the window's title bar: jobs/send-invoice.ts. At most 60 characters. */
  filename?: string | null;
  /** For the highlighter: ts, tsx, js, python, go, bash, json, yaml…; another language shows as plain text. At most 16 characters. */
  language?: string | null;
  /** Code. At most 1600 characters. */
  code: string;
}

/** What Hero shows: one value per content field of items/sections/hero/item.json. */
export interface HeroContent {
  /** A short line above the heading: a launch, a category. At most 48 characters. */
  eyebrow?: string | null;
  /** Heading. At most 90 characters. */
  heading: string;
  /** Lead. At most 240 characters. */
  lead?: string | null;
  /** Buttons. 0–2 items. */
  actions?: Action[] | null;
  /** Small print under the buttons. At most 80 characters. */
  note?: string | null;
  /** A product screen or illustration. Loaded eagerly: it is above the fold. Variants: split, stacked, poster, panel. */
  image?: ImageRef | null;
  /** A full-bleed photo behind the text, cropped to fill (set the hotspot). Loaded eagerly. Leave the alt text empty unless the photo says something the text doesn't. Variants: overlay. */
  background?: ImageRef | null;
  /** Where the subject of the picture is, so a crop (a phone, an ultra-wide screen) keeps it: object-position. Variants: overlay. Default: "center". */
  imageFocus?: 'center' | 'top' | 'bottom' | 'left' | 'right' | 'top left' | 'top right' | 'bottom left' | 'bottom right' | null;
  /** One command under the buttons, with a copy button: npm install @acme/sdk. No prompt sign: it is drawn. At most 80 characters. Variants: code. */
  command?: string | null;
  /** The code window beside the text: a short example of the product in use, highlighted at build time. Variants: code. */
  code?: HeroCode | null;
  /** The layout: centered (Centred), split (Split), stacked (Stacked), overlay (Photo overlay), code (Code), poster (Poster), panel (Panel). Default: "centered". */
  variant?: HeroVariant | null;
  /** The ground: the page’s own, a quiet band (muted), inverse, or accent (the primary colour as ground). Default: "default". */
  tone?: Tone | null;
  /** The room above and below: tight (0.6×), normal or roomy (1.6× space.section). Default: "normal". */
  spacing?: Spacing | null;
  /** Draw the decorative hairlines (above rows, under heads, inside cards). Off: the section separates by space and ground. Default: false. */
  rules?: boolean | null;
}

/** The values a component uses for empty fields (and the Studio's initial values). */
export const HERO_DEFAULTS = { variant: 'centered', tone: 'default', spacing: 'normal', rules: false, imageFocus: 'center' } as const;
